  peer=factory.createPeerConnection(config,new PeerConnection.Observer(){
   public void onSignalingChange(PeerConnection.SignalingState s){} public void onIceConnectionChange(PeerConnection.IceConnectionState s){if(!closed){ui.status("Conexão: "+s);if(s==PeerConnection.IceConnectionState.CONNECTED||s==PeerConnection.IceConnectionState.COMPLETED)ui.connected();if(s==PeerConnection.IceConnectionState.FAILED)ui.error(new Exception("ICE falhou. Verifique rede e região."));}}
   public void onIceConnectionReceivingChange(boolean b){}public void onIceGatheringChange(PeerConnection.IceGatheringState s){}public void onIceCandidate(IceCandidate i){candidates.add(i);}public void onIceCandidatesRemoved(IceCandidate[] c){}public void onAddStream(MediaStream s){}public void onRemoveStream(MediaStream s){}public void onDataChannel(DataChannel d){}public void onRenegotiationNeeded(){}
   public void onAddTrack(RtpReceiver r,MediaStream[] streams){if(r.track() instanceof VideoTrack){video=(VideoTrack)r.track();video.addSink(view);sendControl(Json.obj("message","videoKeyframeRequested","ifrRequested",false));}else if(r.track() instanceof AudioTrack){((AudioTrack)r.track()).setEnabled(true);}}
  });if(peer==null)throw new Exception("Falha ao criar WebRTC");
