 void send(String name,JSONObject j){if(closed)return;DataChannel d=channels.get(name);if(d!=null&&d.state()==DataChannel.State.OPEN)d.send(new DataChannel.Buffer(ByteBuffer.wrap(j.toString().getBytes(StandardCharsets.UTF_8)),false));}
 String awaitOffer()throws Exception{CompletableFuture<String> f=new CompletableFuture<>();peer.createOffer(new Sdp(){public void onCreateSuccess(SessionDescription d){f.complete(d.description);}public void onCreateFailure(String s){f.completeExceptionally(new Exception(s));}},new MediaConstraints());return f.get(20,TimeUnit.SECONDS);}
