 void report(RTCStatsReport report){if(closed)return;for(RTCStats s:report.getStatsMap().values()){Map<String,Object> m=s.getMembers();if(s.getType().equals("inbound-rtp")&&"video".equals(m.get("kind"))){double now=s.getTimestampUs()/1000000.0,bytes=n(m,"bytesReceived"),frames=n(m,"framesDecoded"),decode=n(m,"totalDecodeTime");boolean delta=s.getId().equals(lastId)&&now>lastTime&&frames>=lastFrames;String br=delta?String.format(Locale.US,"%.1f",8*(bytes-lastBytes)/(now-lastTime)/1000000):"—";String ms=delta&&m.containsKey("totalDecodeTime")&&frames>lastFrames?String.format(Locale.US,"%.2f",1000*(decode-lastDecode)/(frames-lastFrames)):"—";
   ui.stats(m.getOrDefault("frameWidth","?")+"×"+m.getOrDefault("frameHeight","?")+" • "+m.getOrDefault("framesPerSecond","?")+" fps • "+br+" Mb/s\nDecode "+ms+" ms • perdidos "+m.getOrDefault("packetsLost","?")+" • "+m.getOrDefault("decoderImplementation",codec+" hardware"));lastId=s.getId();lastTime=now;lastBytes=bytes;lastFrames=frames;lastDecode=decode;}}}
 static double n(Map<String,Object> m,String key){Object v=m.get(key);return v instanceof Number?((Number)v).doubleValue():0;}
 void close(){if(closed)return;closed=true;cloud.stopped=true;if(audio!=null)audio.setMicrophoneMute(true);main.removeCallbacksAndMessages(null);pad.reset();worker.execute(()->{try{cloud.stop();if(video!=null)video.removeSink(view);for(DataChannel d:channels.values()){d.unregisterObserver();d.close();d.dispose();}channels.clear();if(peer!=null){peer.close();peer.dispose();}if(micTrack!=null){micTrack.setEnabled(false);micTrack.dispose();}if(micSource!=null)micSource.dispose();if(factory!=null)factory.dispose();if(audio!=null)audio.release();}finally{main.post(()->{view.release();egl.release();});worker.shutdownNow();}});}
